import{_ as n,o as e,c as t,ag as i}from"./chunks/framework.Dx86EdC1.js";const b=JSON.parse('{"title":"APBDes (Transparansi Anggaran)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/apbdes.md","filePath":"panduan-pengguna/apbdes.md","lastUpdated":1791382762000}'),r={name:"panduan-pengguna/apbdes.md"};function l(s,a,d,o,g,p){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="apbdes-transparansi-anggaran" tabindex="-1">APBDes (Transparansi Anggaran) <a class="header-anchor" href="#apbdes-transparansi-anggaran" aria-label="Permalink to &quot;APBDes (Transparansi Anggaran)&quot;">​</a></h1><p>Menu <strong>APBDes → Anggaran</strong> (<code>/admin/budgets</code>) mengelola Anggaran Pendapatan dan Belanja Desa sesuai <strong>Permendagri No. 20/2018</strong>.</p><h2 id="struktur-data" tabindex="-1">Struktur Data <a class="header-anchor" href="#struktur-data" aria-label="Permalink to &quot;Struktur Data&quot;">​</a></h2><p>Satu record <strong>Anggaran</strong> per tahun, terdiri atas tiga pos <strong>Item</strong>:</p><table tabindex="0"><thead><tr><th>Posisi</th><th>Tipe</th><th>Contoh</th></tr></thead><tbody><tr><td>Pendapatan</td><td><code>revenue</code></td><td>Dana Desa, ADD, PAD, transfer lain</td></tr><tr><td>Belanja</td><td><code>expenditure</code></td><td>5 bidang belanja baku</td></tr><tr><td>Pembiayaan</td><td><code>financing</code></td><td>SiLPA (penerimaan), Penyertaan Modal BUMDes (pengeluaran)</td></tr></tbody></table><p>Setiap item memiliki <strong>anggaran</strong> (<code>budgeted_amount</code>) dan <strong>realisasi</strong> (<code>realized_amount</code>).</p><h2 id="_5-bidang-belanja-baku" tabindex="-1">5 Bidang Belanja Baku <a class="header-anchor" href="#_5-bidang-belanja-baku" aria-label="Permalink to &quot;5 Bidang Belanja Baku&quot;">​</a></h2><p>Sistem mengelompokkan belanja ke lima bidang resmi:</p><ol><li>Penyelenggaraan Pemerintahan</li><li>Pelaksanaan Pembangunan</li><li>Pembinaan Kemasyarakatan</li><li>Pemberdayaan Masyarakat</li><li>Penanggulangan Bencana/Darurat</li></ol><p>Pengelompokan otomatis dipakai untuk visualisasi infografis (lihat test <code>BudgetPermendagriComplianceTest</code>).</p><h2 id="langkah-input" tabindex="-1">Langkah Input <a class="header-anchor" href="#langkah-input" aria-label="Permalink to &quot;Langkah Input&quot;">​</a></h2><ol><li><strong>Tambah Anggaran</strong> — pilih tahun anggaran.</li><li>Buka detail anggaran → <strong>Tambah Item</strong>: <ul><li>Pilih pos (pendapatan/belanja/pembiayaan).</li><li>Isi nama, kode, anggaran, realisasi.</li><li>Untuk belanja: pilih bidang/sub-bidang baku.</li></ul></li><li>Edit atau hapus item bila ada revisi APBDes.</li><li>Publikasikan (status publish) — anggaran tampil di portal.</li></ol><h2 id="tampilan-publik" tabindex="-1">Tampilan Publik <a class="header-anchor" href="#tampilan-publik" aria-label="Permalink to &quot;Tampilan Publik&quot;">​</a></h2><p>Anggaran tampil di <strong><code>/apbdes</code></strong> berupa:</p><ul><li>Ringkasan pendapatan, belanja, pembiayaan (anggaran vs realisasi).</li><li>Grafik komposisi per bidang.</li><li>Tabel rincian item.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nominal cukup diisi dalam rupiah bulat; sistem menjumlahkan agregat. Pastikan total pendapatan − belanja = pembiayaan agar laporan valid.</p></div>',16)])])}const m=n(r,[["render",l]]);export{b as __pageData,m as default};
